//----- (0040BA48) --------------------------------------------------------
void ClearAllMaps()
{
	memzero(FlagMap);
	memzero(PlayerMap);
	memzero(MonsterMap);
	memzero(DeathMonstersMap);
	memzero(BloodMap);
	memzero(ObjectsMap);
	memzero(ItemMap);
	memzero(MissilesMap);
	memzero(ArchGraphicsMap);
	int darkLevel;
	if( FullLighting ){         //  (rt) fully light the level
		darkLevel = 0;
	}else if( Light4Levels ){ // (rt) normal lighting
		darkLevel = 3;
	}else{                      // (rt) complete darkness
		darkLevel = 15;
	}
	memset( LightMap, darkLevel, sizeof( LightMap ) );
	// (th4): seed StaticLightMap with the level's base darkness. SavePreLighting() existed
	// for exactly this but had NO callers -- the call was evidently lost during lighting
	// rework. Without it, StaticLightMap holds zeros (0 = FULLY LIT) or stale data from a
	// previous level, and every DoUnLight() -- the "erase light from its old cell" step of
	// ProcessLightList(), run for EVERY light that moves or goes off -- restores that
	// garbage instead of darkness. That is the root of the misplaced/glitching light family
	// (boss lights, warp light leftovers, etc). ClearAllMaps() is the single choke point
	// every generation path goes through, so one call here covers all of them. On save
	// load this seed is simply overwritten by the StaticLightMap stored in the save.
	SavePreLighting();
}

//----- (0040BAFD) --------------------------------------------------------
void __fastcall LoadQuestDungeonMainMapChurch(char* dunFileName, int playerRowPos, int playerColPos)
{
	MapStartRow = 16;
	MapStartCol = 16;
	MapEndRow = 96;
	MapEndCol = 96;
	ClearWallsTransparency();
	ushort* dunData = (ushort*)LoadFile(dunFileName);

	for( int col = 0; col < Map_40; col++ ){
		for( int row = 0; row < Map_40; row++ ){
			FixedMap[ row ][ col ] = FF_NO;
			Map[ row ][ col ] = CHR_WAFM_22_BEYOND;
		}
	}

	ushort rowSize = dunData[0];
	ushort colSize = dunData[1];
	ushort* dunArray = &dunData[2];

	for( int col = 0; col < colSize; col++ ){
		for( int row = 0; row < rowSize; row++ ){
			ushort wallAndFloorMapValue = dunArray[row + col * rowSize];
			if( wallAndFloorMapValue ){
				FixedMap[ row ][ col ] |= FF_8_FIXED;
				Map[ row ][ col ] = (uchar)wallAndFloorMapValue;
			}else{
				Map[ row ][ col ] = CHR_WAFM_13_FLOOR;
			}
		}
	}

	RandomizeChurchFloorTiles();
	PlayerRowPos = playerRowPos;
	PlayerColPos = playerColPos;
	InitLevelTiles( CHR_WAFM_22_BEYOND );
	ClearAllMaps();
	if( Dungeon->graphType < DT_5_CRYPT ){
		InitChurchArchs();
	}else{
		InitHellfireArchs();
	}
	AddQuestMonsters((ushort*)dunData, 0, 0);
	SetMapObjects((int)dunData, 0, 0);
	// Geometry-derived wall transparency for every church quest map (randomized layouts,
	// expanded rooms). Replaces the need for per-map MapAreas* rectangles.
	InitChurchWallsTransparency();
	ChurchSetAdditionalWallsTransparency(); 
	FreeMem(dunData);
}

//----- (0040BBF3) --------------------------------------------------------
void RandomizeChurchFloorTiles()
{
	for( int col = 0; col < Map_40; col++ ){
		for( int row = 0; row < Map_40; row++ ){
			if( ! FixedMap[ row ][ col ] && Map[ row ][ col ] == CHR_WAFM_13_FLOOR ){
				switch( RNG(3) ){
					case 1:		Map[ row ][ col ] = CHR_WAFM_162_FLOOR_2;		break;
					case 2:		Map[ row ][ col ] = CHR_WAFM_163_FLOOR_3;		break;
				}
			}
		}
	}
}

//----- (0040BC41) --------------------------------------------------------
void InitLevelTiles( int beyondTileNum )
{
	TileSquare* currentLevelTilesFile = (TileSquare*)CurrentLevelTilesFile;
	TileSquare& beyondTile = currentLevelTilesFile[ beyondTileNum -1 ];

	// (rt) fill the whole map with Beyond tiles
	for( int col = 0; col < 112; col += 2 ){
		for( int row = 0; row < 112; row += 2 ){
			Cell fine(FineMap, row, col);
			fine(0, 0) = beyondTile.up    + 1;
			fine(1, 0) = beyondTile.left  + 1;
			fine(0, 1) = beyondTile.right + 1;
			fine(1, 1) = beyondTile.down  + 1;
		}
	}

	// (rt) walk every cell and fill it with values from the loaded TIL file
	for( int col = 0; col < Map_40; col++ ){
		for( int row = 0; row < Map_40; row++ ){
			uchar wafm = Map[ row ][ col ];
			ushort up = 0;
			ushort left = 0;
			ushort right = 0;
			ushort down = 0;
			if( wafm ){
				TileSquare& currentTile = currentLevelTilesFile[ wafm-1 ];
				up    = currentTile.up    + 1;
				left  = currentTile.left  + 1;
				right = currentTile.right + 1;
				down  = currentTile.down  + 1;
			}
			Cell fine(FineMap, Convert40to112(row), Convert40to112(col));
			fine(0, 0) = up;
			fine(1, 0) = left;
			fine(0, 1) = right;
			fine(1, 1) = down;
		}
	}
}

// 1-16 level
//----- (0040BD33) --------------------------------------------------------
void InitChurchArchs()
{
	for( int i = 0; i < 112*112; i++ ){
		switch( FineMap[ 0 ][ i ] ){
		case 12:
		case 71:
		case 211:
		case 321:
		case 341:
		case 418:
			ArchGraphicsMap[ 0 ][ i ] = 1;
			break;
		case 11:
		case 249:
		case 325:
		case 331:
		case 344:
		case 421:
			ArchGraphicsMap[ 0 ][ i ] = 2;
			break;
		case 255:
			ArchGraphicsMap[ 0 ][ i ] = 4;
			break;
		case 259:
			ArchGraphicsMap[ 0 ][ i ] = 5;
			break;
		}
	}
}

//----- (0040BDEE) --------------------------------------------------------
void __fastcall LoadQuestDungeonAltMapChurch( char* fileName, int a2, int a3 )
{
	MapStartRow = 16;
	MapStartCol = 16;
	MapEndRow = 96;
	MapEndCol = 96;


	ushort* dunData = (ushort*)LoadFile(fileName);

	for( int col = 0; col < Map_40; col++ ){
		for( int row = 0; row < Map_40; row++ ){
			FixedMap[ row ][ col ] = FF_NO;
			Map[ row ][ col ] = CHR_WAFM_22_BEYOND;
		}
	}
	ushort rowSize = dunData[0];
	ushort colSize = dunData[1];
	ushort* dunArray = &dunData[2];

	for( int col = 0; col < colSize; col++ ){
		for( int row = 0; row < rowSize; row++ ){
			ushort wallAndFloorMapValue = dunArray[row + col * rowSize];
			if( wallAndFloorMapValue ){
				FixedMap[ row ][ col ] |= FF_NO;
				Map[ row ][ col ] = (uchar)wallAndFloorMapValue;
			}else{
				Map[ row ][ col ] = CHR_WAFM_13_FLOOR;
			}
		}
	}

	RandomizeChurchFloorTiles();

	//(rt) the compiler optimizes this into memcpy( AltMap, Map, sizeof( Map ) ) by itself
	for( int col = 0; col < Map_40; col++ ){
		for( int row = 0; row < Map_40; row++ ){
			AltMap[ row ][ col ] = Map[ row ][ col ];
		}
	}
	FreeMem(dunData);
}

// loadingMode == 1 start new game
//----- (0040BEB8) --------------------------------------------------------
void __fastcall CreateChurchTypeLabyrinth(int levelRandomSeed, int lvlDir) // CreateL5Dungeon
{
	SetRndSeed(levelRandomSeed);
	// (rt) level generation can always be optimized
	// TODO: check this WFT for possible endless loop and actual needing
	if( true /*IsExeValidating*/ && StartLevelSeed[ DUN_0_TOWN ] == RandomSeed && MatchLevelSeed[ (DUNGEON)Dungeon ] ){
		RandomSeed = MatchLevelSeed[ (DUNGEON)Dungeon ];
	}else{
		StartLevelSeed[ (DUNGEON)Dungeon ] = RandomSeed;
		MatchLevelSeed[ (DUNGEON)Dungeon ] = 0;
	}
	MapStartRow = 16;
	MapStartCol = 16;
	MapEndRow = 96;
	MapEndCol = 96;
	UberRow = 0;
	UberCol = 0;
	IsUberRoomOpened = 0;
	SomeDword_64 = 0;
	UberLeverRow = 0;
	UberLeverCol = 0;
	IsUberLeverActivated = 0;
	UberDiabloMonsterIndex = 0;
	ClearWallsTransparency();
	ClearCurPattern();

	ChurchLevelGeneration(lvlDir);
	InitLevelTiles( CHR_WAFM_22_BEYOND );
	if( Dungeon->graphType >= DT_5_CRYPT ){
		InitHellfireArchs();
	}else{
		InitChurchArchs();
	}
	// TODO: add flag for allow theme objects dynamic position ?
	//for( QuestPattern& qp: QuestPatterns ) if( qp.sizeRow >= BigPatternSize && qp.placed ){
		MarkPatternPositionOnMap(/*qp*/);
	//}
	for( int col = MapStartCol; col < MapEndCol; ++col ){
		for( int row = MapStartRow; row < MapEndRow; ++row ){
			int cell = FineMap[ row ][ col ];
			if( cell == 290 ){
				UberRow = row;
				UberCol = col;
			}
			if( cell == 317 ){
				RowOfCornerStone = row;
				ColOfCornerStone = col;
			}
		}
	}
}

//----- (th4) -------------------------------------------------------------
bool LoadQuestPattern(QuestPattern& qp)
{
	if( qp.name ){
		qp.dun = (ushort*)LoadFile(qp.name);
		qp.sizeRow = qp.dun[0];
		qp.sizeCol = qp.dun[1];
		return true;
	}else if( qp.tiles ){
		qp.sizeRow = qp.tiles[0];
		qp.sizeCol = qp.tiles[1];
		return true;
	}
	return false;
}

//----- (th4) -------------------------------------------------------------
void FreeQuestPattern(QuestPattern& qp)
{
	FreeMemZero(qp.dun);
}

