//----- (0040C07F) --------------------------------------------------------
void __fastcall ChurchLevelGeneration(int lvlDir) // DRLG_L5
{
	// (rt) Outbreak: load the arena instead of a normal level
	if (GameMode == GM_OUTBREAK && Dungeon == DUN_1_CHURCH_1) {
		// (rt) Load the map (it adds the monsters from the DUN file)
		LoadQuestDungeonMainMapChurch("Levels\\L1Data\\ob_01.DUN", 40, 40);

		LoadPalette("Levels\\L1Data\\L1_1.pal");
		AddDoorsAndLibrazObjectInChurch(0, 0, 112, 112);
		PlayerRowPos = 23;
		PlayerColPos = 28;
				
		// (rt) Remove procedural monsters but keep the ones from the DUN file
		// (rt) For that we need to know how many monsters the DUN file added.
		// (rt) Simplest way: reload the monsters from the DUN file.

		// (rt) Remember how many monsters there were BEFORE the procedural ones were added
		// (rt) But the procedural ones are added AFTER this function returns.
		// (rt) So procedural generation has to be prevented.

		// (rt) Set a flag that the level is already fully loaded
		// (rt) Main.cpp has a variable "levelGenerated" or similar

		return;
	}

	int isGenerationEnd;
	int maxLevelArea;
	switch( (DUNGEON)Dungeon ){ //(rt) The dungeon's area depends on the floor
	case DUN_1_CHURCH_1: maxLevelArea = 533; break; //(L5DUNX*L5DUNY)/3;
	case DUN_2_CHURCH_2: maxLevelArea = 693; break; //((L5DUNX*L5DUNY)/3) + ((L5DUNX*L5DUNY)/10);
	default:             maxLevelArea = 761; break; //((L5DUNX*L5DUNY)/3) + ((L5DUNX*L5DUNY)/7); and crypt levels
	}
	do{
		ClearWarps();
		//(rt) Clears HallMap and TransparentModes and sets WallTransparentIndex = 1
		ClearWallsTransparency();
		//(rt) Generate the dungeon's binary pattern (walls only (0) and floor (1))
		//(rt) Runs until the required area is reached (area = number of cells with value 1 (floor))
		int levelSeed = 0;
		do{
			levelSeed = RandomSeed;
			ClearGenerationMap(); //(rt) zero the map
			ConstructChurchRooms(); //(rt) build the binary pattern
		}while( AreaOfLevelRoomsChurch() < maxLevelArea );
		if( ! MatchLevelSeed[ (DUNGEON)Dungeon ] && StartLevelSeed[ (DUNGEON)Dungeon ] ){
			MatchLevelSeed[ (DUNGEON)Dungeon ] = levelSeed;
		}
		//(rt) Copies the 40x40 binary pattern into the 80x80 array (1 source cell fills 4 target cells)
		CopyChurchInitalRoomsScheme();
		InitChurchWallAndFloorMapFromBynaryPattern();
		SetupChurchHallsPassagesAndPlaceSpecialPatternsInRandomHall();
		ConvertToChurchWalls();
		bool isAntibottleNeckOn = false;
		switch( Difficulty ){
		case DL_0_HORROR:		isAntibottleNeckOn = Dungeon == DUN_24_CRYPT_4;	break; // TODO: check for DUNGEON id needing, instead of level
		case DL_1_PURGATORY:	isAntibottleNeckOn = Dungeon->level >= 4;	break; // TODO: check for DUNGEON id needing, instead of level
		case DL_2_DOOM:			
		case DL_3_CRUCIBLE:
		case DL_4_TORMENT:
		case DL_5_AGONY:
		case DL_6_TERROR:			
		case DL_7_DESTRUCTION:
		case DL_8_INFERNO:		isAntibottleNeckOn = true;					break;
		}
		if( !isAntibottleNeckOn ){
			ChurchMakeSomeCrossWalls();
		}
		ClearWallFlagMapBit7();
		InitChurchWallsTransparency();
		//(rt) below, GeneratePatternObject places specific tiles or whole patterns of tiles that are objects:
		//(rt) stairs between levels, various decorations such as torches and holes in walls, and so on.
		isGenerationEnd = 1;
		bool goFromUp = lvlDir == LVL_0_DOWN;
		bool goFromDown = lvlDir == LVL_1_UP;
		bool goFromTown = lvlDir >= LVL_2_SET; // TODO: check this out
		//(rt) -------Poisoned Water Supply quest-------------------------------------
		if( Dungeon == DUN_1_CHURCH_1 && MaxCountOfPlayersInGame == 1 && is(GameMode, GM_IRONMAN, /*GM_EASY, GM_CLASSIC, GM_SPEEDRUN, GM_NIGHTMARE, */ GM_SURVIVAL)
		 || IsQuestOnLevel(Q_13_POISONED_WATER_SUPPLY) ){
			if( GenerateChurchPatternObject(PatMap6x6_WaterSupplyEnter, 1, 1, 0, 0, goFromUp, -1, 0) < 0 ){ // (rt) entrance to the poisoned water supply
				isGenerationEnd = 0;
			}
			if( goFromUp ) --PlayerColPos;
		}
		//(rt) -------Ogden's stolen tavern sign quest-------------------------------------
		if( IsQuestOnLevel(Q_7_OGDENS_SIGN) ){
			MatchLevelSeed[ (DUNGEON)Dungeon ] = 0; // TODO: check WTF is this
			if( GenerateChurchPatternObject(PatMap4x4_ChurchPassageUp, 1, 1, 0, 0, goFromUp, -1, 0) < 0 ){
				isGenerationEnd = 0;
			}
			if( goFromUp ) continue; // TODO: check WTF is this
			if( goFromDown ){
				PlayerRowPos = 2 * CurPattern.row + 20; // TODO: check WTF is this
				PlayerColPos = 2 * CurPattern.col + 28;
			}else{
				--PlayerColPos; // TODO: check WTF is this, looks like never excecute
			}
			continue; // TODO: check WTF is this
		}
		if( Dungeon == DUN_21_CRYPT_1 && not(GameMode, GM_NIGHTMARE, GM_SPEEDRUN) ){
			if( GenerateChurchPatternObject(Pat3Map4x5_CryptPassageToTown, 1, 1, 0, 0, goFromTown, -1, 6) < 0 ){
				isGenerationEnd = 0;
			}
		}
		if( Dungeon->graphType == DT_5_CRYPT ){
			if( GenerateChurchPatternObject(PatMap4x5_CryptPassageUp, 1, 1, 0, 0, goFromUp || goFromDown || Dungeon != DUN_21_CRYPT_1, -1, 0) < 0 ){
				isGenerationEnd = 0;
			}
		}else{ // Dungeon->graphType == DT_1_CHURCH
			if( GenerateChurchPatternObject(PatMap4x4_ChurchPassageUp, 1, 1, 0, 0, goFromUp, -1, 0) < 0 ){
				isGenerationEnd = 0;
			}
		}
		if( Dungeon->graphType == DT_5_CRYPT ){
			if( Dungeon != DUN_24_CRYPT_4 ){
				if( GenerateChurchPatternObject(Pat2Map4x5_CryptPassageDown, 1, 1, 0, 0, goFromDown, -1, 1) < 0 ){
					isGenerationEnd = 0;
				}
			}
		}else{ // Dungeon->graphType == DT_1_CHURCH
			if( GenerateChurchPatternObject(PatMap4x3_ChurchPassageDown, 1, 1, 0, 0, goFromDown, -1, 1) < 0 ){
				isGenerationEnd = 0;
			}
		}
		// TODO: may be move here all patterns above
		if( ! PlaceSmallQuestPatterns() ){
			isGenerationEnd = 0;
		}
		if( ! isGenerationEnd ){
			MatchLevelSeed[ (DUNGEON)Dungeon ] = 0;
		}
		if( Dungeon->graphType == DT_5_CRYPT  ){
			if( goFromDown ) PlayerColPos += 3;
			if( goFromUp ) PlayerColPos += 1;
		}else{ // Dungeon->graphType == DT_1_CHURCH
			if( goFromDown ) --PlayerColPos;
		}
	}while( !isGenerationEnd ); // End of room map generation
	IronManMemorialFlag = false;
	// (rt) if the cell is CHR_WAFM_64_CHURCH_LEDDER_TO_UP_2, its room ownership is copied to the neighbouring cells
	// (rt) breakpoint for comparison after a successful level map generation
	// (rt) comparison point: without optimization MatchLevelSeed - 10592019, with optimization - 46909
	for( int col40 = 0; col40 < Map_40; col40++ ){
		for( int row40 = 0; row40 < Map_40; row40++ ){
			if( Map[ row40 ][ col40 ] == CHR_WAFM_64_CHURCH_LEDDER_TO_UP_2 ){
				int col112 = Convert40to112(col40);
				int row112 = Convert40to112(row40);
				CopyCellTransparency(row112, col112 + 1, row112, col112);//shift transparency to right(row upper)
				CopyCellTransparency(row112 + 1, col112 + 1, row112 + 1, col112);//shift transparency to right (row downer)
			}
		}
	}
	//(rt) auto-tiling continues again
	ChurchSetAdditionalWallsTransparency();// (rt) change ownership of Beyond tiles adjoining a room to that room
	SomeConvertChurchAndCryptWalls();
	SomeMoreChurchWallsConvert(); // (rt) left un-rewritten. In 20+ generations all of its conditions were never met at once. 
	//(rt) And since it changes nothing, it cannot be tested. 
	for( int col = 0; col < Map_40; col++ ){
		for( int row = 0; row < Map_40; row++ ){
			if( FixedMap[ row ][ col ] & FF_FIXED_MASK ){// (rt) check the last 7 bits
				ChurchPlaceDoorTiles(row, col);// (rt) place door tiles
			}
		}
	}
	if( Dungeon < DUN_21_CRYPT_1 ){//Diablo Original
		ChurchTilesVariationsChange();// (rt) tiles that have several variants get a 25% chance of a random change
		InitChurchStaticShadows();// (rt) place static shadows
		GenerateChurchPatternObject(PatMap2x2_ChurchOnFloorTorch, 5, 10, 0, 0, 0, -1, 4);// (rt) self-explanatory. Place 5 to 10 lamps
		RandomizeChurchFloorTiles(); // (rt) every cell that is still floor is visited and gets 1 of 3 variations
	}else{ //Hellfire
		//(rt) placement of objects and decoration for Hellfire levels
		if( Dungeon->graphType == DT_5_CRYPT ){ // crypt
			PlaceSomeCryptPatterns_1(10);
			PlaceCryptPatternOnMap(CryptArcLeft, 95);
			PlaceCryptPatternOnMap(CryptArcRight, 95);
			PlaceCryptPatternOnMap(CryptGrateLeft, 100);
			PlaceCryptPatternOnMap(CryptGrateRight, 100);
			PlaceCryptPatternOnMap(CryptBigFloor, 60);
			InitSomeCryptLavaFloorCells();
			switch( (DUNGEON)Dungeon ){
			case DUN_21_CRYPT_1:
				PlaceSomeCryptPatterns_2(30);
				PlaceSomeCryptPatterns_3(15);
				PlaceSomeCryptPatterns_4(5);
				InitSomeCryptLavaFloorCells();
				PlaceSomeCryptPatterns_6(10);
				PlaceSomeCryptPatterns_7(5);
				PlaceSomeCryptPatterns_5(20);
				break;
			case DUN_22_CRYPT_2:
				PlaceSomeCryptPatterns_6(10);
				PlaceSomeCryptPatterns_7(10);
				PlaceSomeCryptPatterns_5(20);
				PlaceSomeCryptPatterns_2(30);
				PlaceSomeCryptPatterns_3(20);
				PlaceSomeCryptPatterns_4(10);
				InitSomeCryptLavaFloorCells();
				break;
			case DUN_23_CRYPT_3:
				PlaceSomeCryptPatterns_6(10);
				PlaceSomeCryptPatterns_7(15);
				PlaceSomeCryptPatterns_5(30);
				PlaceSomeCryptPatterns_2(30);
				PlaceSomeCryptPatterns_3(20);
				PlaceSomeCryptPatterns_4(15);
				InitSomeCryptLavaFloorCells();
				break;
			case DUN_24_CRYPT_4:
				PlaceSomeCryptPatterns_6(10);
				PlaceSomeCryptPatterns_7(20);
				PlaceSomeCryptPatterns_5(30);
				PlaceSomeCryptPatterns_2(30);
				PlaceSomeCryptPatterns_3(20);
				PlaceSomeCryptPatterns_4(20);
				InitSomeCryptLavaFloorCells();
				break;
			}
		}
	}
	for( int i = 0; i < 40*40; i++ ){
		AltMap[ 0 ][ i ] = Map[ 0 ][ i ];
	}
	ClearAllMaps();
	// TODO: change using global DUNFilePtr, StartPatternRow40, StartPatternCol40 to universal AddWarp with entry pattern data
	AddDungeonQuestPatternToWallMap(CurPattern.row, CurPattern.col); // add quest warps (horazon - SetSomePatternsBlock in SetupChurchHallsPassagesAndPlaceSpecialPatternsInRandomHall)
	if( Dungeon == DUN_24_CRYPT_4 ){
		ApplyUberAltDun(CurPattern.row, CurPattern.col);
	}
}

//----- (0071C250) --------------------------------------------------------
void __fastcall ApplyUberAltDun(int row, int col)
{
	ushort* dunFilePtr = (ushort*) LoadFile( "levels\\l5data\\uberoom2.dun" );
	CurPattern.row = row;
	CurPattern.col = col;
	ushort patternMapRows = dunFilePtr[ 0 ];
	ushort patternMapCols = dunFilePtr[ 1 ];
	CurPattern.sizeRow = patternMapRows;
	CurPattern.sizeCol = patternMapCols;
	int patMapOffset = 2;
	for( int colOffset = 0; colOffset < patternMapCols; colOffset++ ){
		for( int rowOffset = 0; rowOffset < patternMapRows; rowOffset++ ){
			int newTile = dunFilePtr[ 2 + rowOffset + colOffset * patternMapRows ];
			if( newTile ){
				AltMap[ row + rowOffset ][ col + colOffset ] = newTile;
			}
		}
	}
	FreeMem( dunFilePtr );
	
}

//----- (0040C58E) --------------------------------------------------------
void __fastcall ChurchPlaceDoorTiles( int row, int col )
{
	int wallFlagMap = FixedMap[row][col];
	if( wallFlagMap & FF_8_FIXED ){
		FixedMap[row][col] = FF_8_FIXED;
		return;
	}
	uchar* wallAndFloorMap = &Map[row][col];
	int flags = wallFlagMap & FF_FIXED_MASK;
	switch (flags ){
	case FF_1_HDOOR:
		if( col != 1 ){
			switch (*wallAndFloorMap ){
			case CHR_WAFM_2_SWALL_M_MIDLE:									*wallAndFloorMap = CHR_WAFM_26_M_MIDDLE_CLOSED_DOOR;	break;
			case CHR_WAFM_7_SWALL_LU_END:									*wallAndFloorMap = CHR_WAFM_31_CDOOR_LU_END;	break;
			case CHR_WAFM_14_CORNER_BETWEEN_LD_ARCH_AND_RD_SWALL:			*wallAndFloorMap = CHR_WAFM_42_CORNER_BETWEEN_LU_ARCH_AND_RU_CDOOR;	break;
			case CHR_WAFM_4_CORNER_BETWEEN_LD_SWALL_AND_RD_SWALL:			*wallAndFloorMap = CHR_WAFM_43_CORNER_BETWEEN_LU_CWALL_AND_RU_CDOOR;	break;
			}
		}
		if( row != 1 ){
			switch (*wallAndFloorMap ){
			case CHR_WAFM_1_SWALL_UNM_MIDDLE:								*wallAndFloorMap = CHR_WAFM_25_UNM_MIDDLE_CLOSED_DOOR;	break;
			case CHR_WAFM_10_CORNER_BETWEEN_LD_SWALL_AND_RD_ARCH:			*wallAndFloorMap = CHR_WAFM_40_CORNER_BETWEEN_LU_CDOOR_AND_RU_ARCH;	break;
			case CHR_WAFM_6_SWALL_RU_END:									*wallAndFloorMap = CHR_WAFM_30_CDOOR_RU_END;	break;
			}
		}
		break;
	case FF_2_VDOOR:
		if( row != 1 ){
			switch (*wallAndFloorMap ){
			case CHR_WAFM_1_SWALL_UNM_MIDDLE:								*wallAndFloorMap = CHR_WAFM_25_UNM_MIDDLE_CLOSED_DOOR;	break;
			case CHR_WAFM_6_SWALL_RU_END:									*wallAndFloorMap = CHR_WAFM_30_CDOOR_RU_END;	break;
			case CHR_WAFM_10_CORNER_BETWEEN_LD_SWALL_AND_RD_ARCH:			*wallAndFloorMap = CHR_WAFM_40_CORNER_BETWEEN_LU_CDOOR_AND_RU_ARCH;	break;
			case CHR_WAFM_4_CORNER_BETWEEN_LD_SWALL_AND_RD_SWALL:			*wallAndFloorMap = CHR_WAFM_41_CORNER_BETWEEN_LU_CDOOR_AND_RU_CWALL;	break;
			}
		}
		if( col != 1 ){
			switch (*wallAndFloorMap ){
			case CHR_WAFM_2_SWALL_M_MIDLE:									*wallAndFloorMap = CHR_WAFM_26_M_MIDDLE_CLOSED_DOOR;	break;
			case CHR_WAFM_14_CORNER_BETWEEN_LD_ARCH_AND_RD_SWALL:			*wallAndFloorMap = CHR_WAFM_42_CORNER_BETWEEN_LU_ARCH_AND_RU_CDOOR;	break;
			case CHR_WAFM_7_SWALL_LU_END:									*wallAndFloorMap = CHR_WAFM_31_CDOOR_LU_END;	break;
			}
		}
		break;
	case FF_DDOOR:
		if( row != 1 && col != 1 ){
			if( *wallAndFloorMap == CHR_WAFM_4_CORNER_BETWEEN_LD_SWALL_AND_RD_SWALL ){
				*wallAndFloorMap = CHR_WAFM_28_CORNER_BETWEEN_LU_CDOOR_AND_RU_CDOOR;
			}
		}
		if( col != 1 ){
			switch (*wallAndFloorMap ){
			case CHR_WAFM_14_CORNER_BETWEEN_LD_ARCH_AND_RD_SWALL:			*wallAndFloorMap = CHR_WAFM_42_CORNER_BETWEEN_LU_ARCH_AND_RU_CDOOR;	break;
			case CHR_WAFM_2_SWALL_M_MIDLE:									*wallAndFloorMap = CHR_WAFM_26_M_MIDDLE_CLOSED_DOOR;	break;
			case CHR_WAFM_7_SWALL_LU_END:									*wallAndFloorMap = CHR_WAFM_31_CDOOR_LU_END;	break;
			}
		}
		if( row != 1 ){
			switch (*wallAndFloorMap ){
			case CHR_WAFM_1_SWALL_UNM_MIDDLE:								*wallAndFloorMap = CHR_WAFM_25_UNM_MIDDLE_CLOSED_DOOR;	break;
			case CHR_WAFM_6_SWALL_RU_END:									*wallAndFloorMap = CHR_WAFM_6_SWALL_RU_END;	break;
			case CHR_WAFM_10_CORNER_BETWEEN_LD_SWALL_AND_RD_ARCH:			*wallAndFloorMap = CHR_WAFM_40_CORNER_BETWEEN_LU_CDOOR_AND_RU_ARCH;	break;
			}
		}
		break;
	}
	FixedMap[ row ][ col ] = FF_8_FIXED;
}

