//----- (0040E92D) --------------------------------------------------------
void __fastcall CopyCryptLastBossPatternToMap(int row, int col)
{
	UberRow = 2 * row + 6;
	UberCol = 2 * col + 8;
	CurPattern.row = row;
	CurPattern.col = col;
	CurPattern.sizeRow = UberRoomPattern[0];
	CurPattern.sizeCol = UberRoomPattern[1];

	IsUberRoomOpened = 0;
	SomeDword_64 = 0;
	IsUberLeverActivated = 0;

	int patMapOffset = 2;
	for( int colOffset = 0; colOffset < CurPattern.sizeCol; colOffset++ ){
		for( int rowOffset = 0; rowOffset < CurPattern.sizeRow; rowOffset++ ){
			int cell = col + colOffset + 40 * (row + rowOffset);
			int newTile = UberRoomPattern[patMapOffset];
			if( newTile ){
				FixedMap[ 0 ][ cell ] |= FF_8_FIXED;
				Map[ 0 ][ cell ] = newTile;
			}else{
				Map[ 0 ][ cell ] = CHR_WAFM_13_FLOOR;
			}
			patMapOffset++;
		}
	}
}

