//----- (00414D5C) --------------------------------------------------------
void FixingHellPandemoniumTiles()
{
	for( int col = 0; col < 14; col++ ){
		for( int row = 0; row < 14; row++ ){
			FixedMap[ DiabloQuadsStartRow + row ][ DiabloQuadsStartCol + col ] = FF_1_HDOOR;
			FixedMap[ 39 -DiabloQuadsStartRow - row ][ DiabloQuadsStartCol + col ] = FF_1_HDOOR;
			FixedMap[ DiabloQuadsStartRow + row ][ 39 - DiabloQuadsStartCol - col ] = FF_1_HDOOR;
			FixedMap[ 39 -DiabloQuadsStartRow - row ][ 39 - DiabloQuadsStartCol - col ] = FF_1_HDOOR;
		}
	}
}

